    order by loc, anio, mes, numero loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc;
    select id into v_cat from public.catalogos_cuentas where localidad_id = v_loc and version = 1 order by activo desc limit 1;
    if v_cat is null then select id into v_cat from public.catalogos_cuentas where localidad_id = v_loc order by activo desc, version desc limit 1; end if;
    select id into v_tp from public.tipos_partida where siglas = r.siglas;
    v_tr := null;
    select id into v_tr from public.transacciones_contables where localidad_id = v_loc and numero = r.transaccion::integer;
    -- Una partida registrada en el sistema (no migrada) con el mismo número o número anual no se toca: se informa.
    v_ex := null;
    select id, origen_anterior into v_ex from public.partidas where localidad_id = v_loc and ((anio = r.anio and mes = r.mes and numero = r.numero) or (anio = r.anio and numero_anual = r.anual))
      order by (anio = r.anio and mes = r.mes and numero = r.numero) desc limit 1;
    if v_ex.id is not null and v_ex.origen_anterior is distinct from 'MIGRADO' then
      p_s := p_s + 1; v_choques := array_append(v_choques, format('3-0%s %s-%s (anual %s)', r.loc, lpad(r.mes::text, 2, '0'), r.numero, r.anual)); continue;
    end if;
    if v_ex.id is null then
      insert into public.partidas (organizacion_id, localidad_id, catalogo_id, anio, mes, numero, numero_anual, fecha, usuario, tipo_partida_id, descripcion, moneda_id, tipo_cambio,
        origen, estado, aprobada, definitiva, clasificacion, origen_anterior)
      values (v_org, v_loc, v_cat, r.anio, r.mes, r.numero, r.anual, coalesce(r.fecha::timestamp, make_date(r.anio, r.mes, 1)::timestamp)::timestamptz, upper(r.usuario::text), v_tp,
        r.descripcion, v_gtq, 1, case when r.tipo = 'A' then 'AUTOMÁTICA' else 'MANUAL' end, 'VIGENTE', false, false, r.clasificacion, 'MIGRADO')
      returning id into v_id;
      p_n := p_n + 1;
    else
      v_id := v_ex.id; p_a := p_a + 1;
    end if;
    -- Una partida definitiva queda también aprobada (en el sistema solo una aprobada pasa a definitiva).
    update public.partidas set catalogo_id = v_cat, anio = r.anio, mes = r.mes, numero = r.numero, numero_anual = r.anual,
      fecha = coalesce(r.fecha::timestamp, make_date(r.anio, r.mes, 1)::timestamp)::timestamptz, usuario = upper(r.usuario::text), tipo_partida_id = v_tp,
      descripcion = r.descripcion, moneda_id = v_gtq, tipo_cambio = 1, origen = case when r.tipo = 'A' then 'AUTOMÁTICA' else 'MANUAL' end,
      estado = case when upper(r.estado::text) = 'V' then 'VIGENTE' else 'ANULADA' end, clasificacion = r.clasificacion,
      aprobada = upper(r.aprobada::text) = 'S' or upper(r.definitiva::text) = 'S', aprobada_por = case when upper(r.aprobada::text) = 'S' or upper(r.definitiva::text) = 'S' then upper(r.usuario::text) end,
      aprobada_en = case when upper(r.aprobada::text) = 'S' or upper(r.definitiva::text) = 'S' then r.fecha::timestamp::timestamptz end,
      definitiva = upper(r.definitiva::text) = 'S', definitiva_por = case when upper(r.definitiva::text) = 'S' then upper(r.usuario::text) end,
      definitiva_en = case when upper(r.definitiva::text) = 'S' then r.fecha::timestamp::timestamptz end,
      origen_anterior = 'MIGRADO', estado_anterior = r.estado, modulo_anterior = r.modulo::integer, tipo_anterior = r.tipo, aprobada_anterior = r.aprobada,
      clasificacion_anterior = r.clasif_ant, transaccion_anterior = r.transaccion::integer, transaccion_id = v_tr, moneda_integracion = r.moneda_int::integer,
      valor_cambio_anterior = r.cambio::numeric, anticipo = r.anticipo::boolean, definitiva_anterior = r.definitiva, revisada = r.revisada::boolean
    where id = v_id;
  end loop;

