    (2, 2025, 6, 1, 194, '6010106002', 1, 710.83, 0, 92.32, 0, 'MOVIMIENTOS JUNIO 2025', 'I', 710.83, 0),
    (2, 2025, 6, 1, 195, '6010105001', 1, 380, 0, 49.35, 0, 'MOVIMIENTOS JUNIO 2025', 'I', 380, 0),
    (2, 2025, 6, 1, 196, '6010103029', 1, 5730.09, 0, 744.17, 0, 'MOVIMIENTOS JUNIO 2025', 'I', 5730.09, 0),
    (2, 2025, 6, 1, 197, '6010103008', 1, 263.39, 0, 34.21, 0, 'MOVIMIENTOS JUNIO 2025', 'I', 263.39, 0),
    (2, 2025, 6, 1, 198, '6010105003', 1, 5713.73, 0, 742.04, 0, 'MOVIMIENTOS JUNIO 2025', 'I', 5713.73, 0),
    (2, 2025, 6, 1, 199, '8010102003', 1, 30, 0, 3.9, 0, 'MOVIMIENTOS JUNIO 2025', 'I', 30, 0)) as x(loc, anio, mes, numero, linea, codigo, version, debe, haber, debe_mi, haber_mi, justificacion, tipo_centro, debito_ant, credito_ant) loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc;
    v_id := null; v_cat := null;
    select id, catalogo_id into v_id, v_cat from public.partidas where localidad_id = v_loc and anio = r.anio and mes = r.mes and numero = r.numero and origen_anterior = 'MIGRADO';
    if v_id is null then l_s := l_s + 1; continue; end if;
    if r.debe = 0 and r.haber = 0 then l_s := l_s + 1; continue; end if;
    v_cta := null;
    select id into v_cta from public.cuentas where catalogo_id = v_cat and codigo = r.codigo;
    if v_cta is null then l_c := l_c + 1; v_faltan := array_append(v_faltan, format('3-0%s %s', r.loc, r.codigo)); continue; end if;
    insert into public.partida_lineas (partida_id, linea, cuenta_id, concepto, debe, haber, debe_mi, haber_mi, cuenta_codigo_anterior, version_cuenta_anterior, tipo_int_centro,
      debito_anterior, credito_anterior, origen_anterior)
    values (v_id, r.linea, v_cta, nullif(trim(r.justificacion::text), ''), r.debe, r.haber, r.debe_mi::numeric, r.haber_mi::numeric, r.codigo, r.version, r.tipo_centro::text,
      r.debito_ant::numeric, r.credito_ant::numeric, 'MIGRADO')
    on conflict (partida_id, linea) do update set cuenta_id = excluded.cuenta_id, concepto = excluded.concepto, debe = excluded.debe, haber = excluded.haber,
      debe_mi = excluded.debe_mi, haber_mi = excluded.haber_mi, cuenta_codigo_anterior = excluded.cuenta_codigo_anterior, version_cuenta_anterior = excluded.version_cuenta_anterior,
      tipo_int_centro = excluded.tipo_int_centro, debito_anterior = excluded.debito_anterior, credito_anterior = excluded.credito_anterior, origen_anterior = 'MIGRADO'
    returning (xmax = 0) into v_nuevo;
    if v_nuevo then l_n := l_n + 1; else l_a := l_a + 1; end if;
    if not v_id = any (v_ids) then v_ids := array_append(v_ids, v_id); end if;
  end loop;
  -- Totales de las partidas que recibieron líneas.
  update public.partidas p set total_debe = coalesce(s.d, 0), total_haber = coalesce(s.h, 0)
  from (select partida_id, sum(debe) d, sum(haber) h from public.partida_lineas where partida_id = any (v_ids) group by partida_id) s
  where s.partida_id = p.id;

  alter table public.partidas enable trigger user;
  alter table public.partida_lineas enable trigger user;
  raise notice '%', format('Partidas: %s nuevas, %s actualizadas, %s no se tocaron (ya existen en el sistema). Detalle: %s líneas nuevas, %s actualizadas, %s omitidas (sin partida o en cero), %s sin cuenta.',
    p_n, p_a, p_s, l_n, l_a, l_s, l_c);
  if p_s > 0 then raise notice 'Partidas del sistema con el mismo número (no se cambiaron; revíselas): %.', array_to_string(v_choques, ', '); end if;
  if l_c > 0 then raise notice 'Cuentas que no existen en el catálogo versión 1 (líneas omitidas): %.', (select string_agg(distinct x, ', ') from unnest(v_faltan) x); end if;
end;
$migra$;

